def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product that can be obtained by inserting K multiplication signs into the number string.

    :param num_str: A string representing the number string.
    :param N: An integer representing the length of the number string.
    :param K: An integer representing the number of multiplication signs to insert.
    :return: The maximum product that can be obtained by inserting K multiplication signs.
    """
    if not num_str or N <= 0 or K < 0 or K >= N:
        return 0

    def split_and_multiply(nums):
        product = 1
        for num in nums:
            if num > 0:
                product *= num
        return product

    def backtrack(start, k, current):
        if k == 0:
            return split_and_multiply([int(num_str[start:])] + current)
        max_product = 0
        for i in range(start, N - k + 1):
            prefix = int(num_str[start:i + 1])
            current_product = split_and_multiply([prefix] + current)
            max_product = max(max_product, current_product * backtrack(i + 1, k - 1, current))
        return max_product

    return backtrack(0, K, [])

